{
    var initInfo = {editable: false,isEditMode: false,allowWebPartAdder: false,listId: "{1081bf92-c74a-47c9-a0a2-d39309232bef}",itemId: 24,recycleBinEnabled: true,enableMinorVersioning: true,enableModeration: false,forceCheckout: true,rootFolderUrl: "\u002far\u002fPages",itemPermissions:{High:16,Low:196673}};
    SP.Ribbon.WebPartComponent.registerWithPageManager(initInfo);
